const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const center = ee.Geometry.Point([-49.053062, -1.593993]);
  const aoi = center.buffer(100000); // 100 km radius
  const startDate = '2009-08-19';
  const endDate = '2009-08-20';

  // 2. Data Acquisition - Try Landsat 5 first, then Landsat 7
  let collection = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(aoi)
    .filterDate(startDate, endDate);

  let collectionSize = collection.size().getInfo();
  console.log(`Landsat 5 images found: ${collectionSize}`);

  if (collectionSize === 0) {
    collection = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
      .filterBounds(aoi)
      .filterDate(startDate, endDate);
    collectionSize = collection.size().getInfo();
    console.log(`Landsat 7 images found: ${collectionSize}`);
  }

  // Try expanding date range if still no data
  if (collectionSize === 0) {
    collection = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
      .filterBounds(aoi)
      .filterDate('2009-08-15', '2009-08-23');
    collectionSize = collection.size().getInfo();
    console.log(`Landsat 5 images (expanded dates): ${collectionSize}`);
  }

  if (collectionSize === 0) {
    console.log("No images found for the specified date and location.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Get image and cloud information
  const image = collection.first();
  const qaband = image.select('QA_PIXEL');

  // Bit 3 is cloud for Landsat Collection 2
  const cloudMask = qaband.bitwiseAnd(1 << 3).gt(0);

  // 4. Get water mask from JRC Global Surface Water
  const water = ee.Image('JRC/GSW1_4/GlobalSurfaceWater').select('occurrence');
  const waterMask = water.gt(50); // Areas that are water >50% of the time
  const landMask = waterMask.not();

  // 5. Calculate cloud coverage over land and water
  const cloudOverLand = cloudMask.updateMask(landMask);
  const cloudOverWater = cloudMask.updateMask(waterMask);

  // Count pixels
  const landCloudStats = cloudOverLand.reduceRegion({
    reducer: ee.Reducer.sum().combine(ee.Reducer.count(), '', true),
    geometry: aoi,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const waterCloudStats = cloudOverWater.reduceRegion({
    reducer: ee.Reducer.sum().combine(ee.Reducer.count(), '', true),
    geometry: aoi,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const landCloudPixels = landCloudStats['QA_PIXEL_sum'] || 0;
  const landTotalPixels = landCloudStats['QA_PIXEL_count'] || 0;
  const waterCloudPixels = waterCloudStats['QA_PIXEL_sum'] || 0;
  const waterTotalPixels = waterCloudStats['QA_PIXEL_count'] || 0;

  console.log(`Land pixels: ${landTotalPixels}, Cloud over land: ${landCloudPixels}`);
  console.log(`Water pixels: ${waterTotalPixels}, Cloud over water: ${waterCloudPixels}`);

  // 6. Check for valid data
  if (landTotalPixels === 0 || waterTotalPixels === 0) {
    console.log("No valid pixels found for land or water areas.");
    console.log("<answer>C2</answer>");
    return;
  }

  // 7. Calculate percentages
  const landCloudPercent = (landCloudPixels / landTotalPixels) * 100;
  const waterCloudPercent = (waterCloudPixels / waterTotalPixels) * 100;

  console.log(`Cloud cover over land: ${landCloudPercent.toFixed(2)}%`);
  console.log(`Cloud cover over rivers: ${waterCloudPercent.toFixed(2)}%`);

  // 8. Validation & Final Answer
  if (isNaN(landCloudPercent) || isNaN(waterCloudPercent)) {
    console.log("Calculation failed - invalid results.");
    console.log("<answer>C3</answer>");
    return;
  }

  if (landCloudPercent > waterCloudPercent) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
